  814: function buildHealthAlertSection(healthReport, callbacks) {
  1125:             const el = buildHealthAlertSection(report, {

801	
802	/**
803	 * Build a health alert section element from a workspace health report.
804	 * Returns `null` when the workspace is healthy (no issues to display).
805	 *
806	 * Fix-action buttons are wired via the `callbacks` argument so the
807	 * caller can inject async handlers that match the surrounding view's
808	 * closure state (project/workspace IDs, toast helper, etc.).
809	 *
810	 * @param {{ healthy: boolean, issues: Array<{ type: string, severity: string, message: string, fixAction: string, repositoryId?: string }> }|null} healthReport
811	 * @param {{ onRegenerate: function(): Promise<void>, onSetup: function(): Promise<void> }} callbacks
812	 * @returns {HTMLElement|null}
813	 */
814	function buildHealthAlertSection(healthReport, callbacks) {
815	    if (
816	        !healthReport ||
817	        healthReport.healthy ||
818	        !Array.isArray(healthReport.issues) ||
819	        healthReport.issues.length === 0
820	    ) {
821	        return null;
822	    }
823	
824	    const section = document.createElement('div');
825	    section.className = 'health-alert';
826	
827	    const title = document.createElement('div');
828	    title.className = 'health-alert-title';
829	    title.textContent = 'Workspace health issues detected';
830	    section.appendChild(title);
831	
832	    for (const issue of healthReport.issues) {
833	        const row = document.createElement('div');
834	        row.className = 'health-alert-issue';
835	
836	        const msg = document.createElement('span');
837	        msg.className = 'health-alert-issue__message';
838	        msg.textContent = issue.message;
839	        row.appendChild(msg);
840	
841	        if (issue.fixAction === 'regenerate-workspace-file') {
842	            const actionWrap = document.createElement('span');
843	            actionWrap.className = 'health-alert-issue__action';
844	
845	            const btn = document.createElement('button');
846	            btn.type = 'button';
847	            btn.className = 'btn btn-secondary btn-sm';
848	            btn.textContent = 'Regenerate File';
849	            btn.addEventListener('click', async () => {
850	                btn.disabled = true;
851	                btn.textContent = 'Regenerating\u2026';
852	                try {
853	                    await callbacks.onRegenerate();
854	                } finally {
855	                    btn.disabled = false;
856	                    btn.textContent = 'Regenerate File';
857	                }
858	            });
859	            actionWrap.appendChild(btn);
860	            row.appendChild(actionWrap);
861	        } else if (issue.fixAction === 'setup-workspace') {
862	            const actionWrap = document.createElement('span');
863	            actionWrap.className = 'health-alert-issue__action';
864	
865	            const btn = document.createElement('button');
866	            btn.type = 'button';
867	            btn.className = 'btn btn-secondary btn-sm';
868	            btn.textContent = 'Fix Setup';
869	            btn.addEventListener('click', async () => {
870	                btn.disabled = true;
871	                btn.textContent = 'Setting up\u2026';
872	                try {
873	                    await callbacks.onSetup();
874	                } finally {
875	                    btn.disabled = false;
876	                    btn.textContent = 'Fix Setup';
877	                }
878	            });
879	            actionWrap.appendChild(btn);
880	            row.appendChild(actionWrap);

881	        } else if (issue.fixAction === 'configure-credential') {
882	            const actionWrap = document.createElement('span');
883	            actionWrap.className = 'health-alert-issue__action';
884	
885	            const btn = document.createElement('button');
886	            btn.type = 'button';
887	            btn.className = 'btn btn-secondary btn-sm';
888	            btn.textContent = 'Configure';
889	            btn.addEventListener('click', () => {
890	                window.location.hash = '#/repositories';
891	            });
892	            actionWrap.appendChild(btn);
893	            row.appendChild(actionWrap);
894	        }
895	        // Issues with an unknown fixAction render the message row without a button.
896	
897	        section.appendChild(row);
898	    }
899	
900	    return section;
901	}
902	
